// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr1, address addr2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);

        // Drive the contract: call XBornID() first
        c.XBornID();

        // Sum balances of two accounts (since totalDistributed is 200e18, owner gets that, others 0)
        uint256 bal1 = c.balanceOf(addr1);
        uint256 bal2 = c.balanceOf(addr2);
        uint256 ownerBal = c.balanceOf(address(this)); // owner is deployer (address(this))

        // The invariant: totalSupply >= totalDistributed >= 0, and sum of all balances <= totalSupply
        // Since we can't iterate all addresses, check that totalDistributed + remaining >= totalDistributed
        // Actually, the invariant is: balanceOf(owner) + balanceOf(any other) <= totalDistributed + totalRemaining
        // After XBornID, owner has totalDistributed, others have 0, so sum == totalDistributed
        // A simple general rule: balanceOf(owner) + balanceOf(any) + balanceOf(other) == totalDistributed + totalRemaining? No, totalRemaining is decremented only in distr() which is not called by XBornID.
        // Let's use a different invariant: The sum of all balances is always <= totalSupply.
        // For a single account, balanceOf(x) <= totalSupply.
        assertTrue(bal1 <= c.totalSupply());
        assertTrue(bal2 <= c.totalSupply());
        assertTrue(ownerBal <= c.totalSupply());
        // Also check that balanceOf(owner) equals totalDistributed after XBornID (reference invariant)
        assertTrue(ownerBal == c.totalDistributed());
    }
}

